"""V3 offline submission inference (generated by build.py; do not edit infer.py by hand).

Ensemble: CONFIG["models"] lists checkpoints, each with its own head / windows / res / mirror. Each
study is read and canonicalised ONCE; windows are filled per (mirror, windows) and every model runs on
it. Per-model probabilities go to probs_<name>.csv; submission = per-finding rank percentile over test
studies, equal-weight mean over the models that succeeded on that study (single model: raw probs).

Preprocessing = cache + train_v3 eval exactly: select_series -> canon.canon_series (bundled
verbatim, SHA-checked) -> optional L->R mirror -> evenly spaced 3-slice windows -> /255, resize to
RES, ImageNet norm -> V3 model. fp16 autocast on GPU (never bf16), fp32 on CPU, batch 1.
No training labels are opened.

Failure policy (every case counted in the summary, never silent):
  1. all selected series load -> normal prediction;
  2. a series fails -> drop only that plane ("degraded");
  3. no plane left -> column mean of successful predictions ("fallback"; never 0.5); same after 8 h.
PARITY_UIDS set -> parity mode: those train studies from train_series, writes probs_<name>.csv, no submission.
"""
import csv
import hashlib
import json
import os
import sys
import time
from collections import Counter, defaultdict
from pathlib import Path

import numpy as np
import pydicom
import torch
from scipy.stats import rankdata
from torch.utils.data import DataLoader, Dataset

SOURCES = __SOURCES__
CONFIG = __CONFIG__
PARITY_UIDS = __PARITY_UIDS__

SRC = Path("/tmp/v3src") if Path("/kaggle").is_dir() else Path(__file__).resolve().parent / "_v3src"
SRC.mkdir(parents=True, exist_ok=True)
for name, text in SOURCES.items():
    if hashlib.sha256(text.encode("utf-8")).hexdigest() != CONFIG["source_sha256"][name]:
        raise ValueError(f"source hash mismatch: {name}")
    (SRC / name).write_text(text, encoding="utf-8")
sys.path.insert(0, str(SRC))
from canon import canon_series  # noqa: E402
from m00_data import ROLES, select_series, select_slots, slot_names  # noqa: E402,F401
from v3_model import V3, TARGETS, fill_windows, mirror, prep  # noqa: E402

COMPETITION_DIRS = (Path("/kaggle/input/rsna-knee-abnormality-detection"),
                    Path("/kaggle/input/competitions/rsna-knee-abnormality-detection"))
CHECKPOINT_DIRS = (Path("/kaggle/input") / CONFIG["dataset"],
                   Path("/kaggle/input/datasets/aymenslimani") / CONFIG["dataset"])
OUT = Path("/kaggle/working") if Path("/kaggle/working").is_dir() else Path(".")
STOP_AT_S = 8 * 3600
WORKERS = 4
VIEWS = sorted({(m["mirror"], m["windows"], m.get("slots", 3)) for m in CONFIG["models"]})
T0 = time.monotonic()


def sha256(path):
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def exactly_one(name, directories):
    hits = {p.resolve() for d in directories if d.is_dir() for p in d.rglob(name)}
    if len(hits) != 1:
        raise FileNotFoundError(f"expected one {name}, found {len(hits)}")
    return hits.pop()


def read_csv(path):
    with path.open(newline="", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))


def read_schema(data):
    if PARITY_UIDS is not None:
        cols, uids, series_csv = ["StudyInstanceUID", *TARGETS], list(PARITY_UIDS), "train_series.csv"
    else:
        rows = read_csv(data / "sample_submission.csv")
        cols = list(rows[0]) if rows else []
        if cols != ["StudyInstanceUID", *TARGETS]:
            raise ValueError("sample submission schema mismatch or empty")
        uids = [r["StudyInstanceUID"] for r in rows]
        if len(uids) != len(set(uids)) or set(uids) != {r["StudyInstanceUID"] for r in read_csv(data / "test.csv")}:
            raise ValueError("duplicate sample UID or test/sample UIDs differ")
        series_csv = "test_series.csv"
    by_study = defaultdict(list)
    for row in read_csv(data / series_csv):
        by_study[row["StudyInstanceUID"]].append(row)
    return cols, uids, by_study


class TestDS(Dataset):
    def __init__(self, root, uids, by_study):
        self.root, self.uids, self.by_study = root, uids, by_study

    def __len__(self):
        return len(self.uids)

    def __getitem__(self, i):
        uid = self.uids[i]
        syntaxes, errors = Counter(), []
        vols, xs, ms, selected = {}, {}, {}, set()
        for n_slots in sorted({v[2] for v in VIEWS}):
            slots = slot_names(n_slots)
            sel = select_slots(self.by_study.get(uid, []), n_slots)
            for v in VIEWS:
                if v[2] == n_slots:
                    xs[v], ms[v] = np.zeros((len(slots), v[1], 3, 256, 256), np.uint8), np.zeros((len(slots), v[1]), bool)
            for r, slot in enumerate(slots):
                series = sel[slot]
                if series is None:
                    continue  # missing slot stays masked
                selected.add(series)
                if series not in vols:  # each series decoded once, shared by every slot config
                    try:
                        paths = sorted((self.root / uid / series).glob("*.dcm"))
                        if not paths:
                            raise FileNotFoundError("selected series has no DICOM files")
                        dss = [pydicom.dcmread(str(p)) for p in paths]
                        syntaxes[str(getattr(dss[0].file_meta, "TransferSyntaxUID", "?"))] += 1
                        vol, meta = canon_series(dss)
                        if len(vol) < 3:
                            raise ValueError("fewer than 3 slices")
                        vols[series] = (vol, mirror(vol, meta["plane_geom"]) if meta["laterality"] == "L" else vol)
                    except Exception as exc:
                        errors.append(f"{slot}:{type(exc).__name__}")
                        vols[series] = None
                if vols[series] is None:
                    continue
                for v in VIEWS:
                    if v[2] == n_slots:
                        fill_windows(xs[v][r], ms[v][r], vols[series][v[0]], v[1])
        state = "failed" if not ms[VIEWS[0]].any() else "degraded" if errors else "ok"
        return {"i": i, "state": state, "x": {v: torch.from_numpy(a) for v, a in xs.items()},
                "mask": {v: torch.from_numpy(a) for v, a in ms.items()},
                "syntaxes": syntaxes, "errors": errors, "n_selected_series": len(selected)}


def write_csv(path, columns, uids, values):
    tmp = path.with_name(path.name + ".tmp")
    with tmp.open("w", newline="", encoding="utf-8") as f:
        w = csv.writer(f, lineterminator="\n")
        w.writerow(columns)
        for uid, p in zip(uids, values):
            w.writerow([uid, *[format(float(v), ".9g") for v in p]])
    os.replace(tmp, path)


def worker_init(_):
    torch.set_num_threads(1)


def main():
    data = next((p for p in COMPETITION_DIRS if (p / "sample_submission.csv").is_file()), None)
    if data is None:
        raise FileNotFoundError("official competition data mount missing")
    columns, uids, by_study = read_schema(data)
    root = data / ("train_series" if PARITY_UIDS is not None else "test_series")
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    print(f"device={device} torch={torch.__version__} pydicom={pydicom.__version__} studies={len(uids)} models={CONFIG['run']}", flush=True)
    models = []
    for spec in CONFIG["models"]:
        checkpoint = exactly_one(spec["checkpoint"], CHECKPOINT_DIRS)
        if sha256(checkpoint) != spec["sha256"]:
            raise ValueError(f"checkpoint SHA256 mismatch: {spec['name']}")
        model = V3(spec["head"], backbone=spec.get("backbone", "resnet18")).to(device).eval()
        model.load_state_dict(torch.load(checkpoint, map_location="cpu", weights_only=True), strict=True)
        models.append((spec, model))

    loader = DataLoader(TestDS(root, uids, by_study), batch_size=None, shuffle=False, num_workers=WORKERS,
                        worker_init_fn=worker_init, multiprocessing_context="fork" if sys.platform == "linux" else None)
    probs = np.full((len(models), len(uids), len(TARGETS)), np.nan)
    states, syntaxes, errors, windows, model_failures = Counter(), Counter(), Counter(), [], Counter()
    timed_out = 0
    for n, item in enumerate(loader, 1):
        if time.monotonic() - T0 > STOP_AT_S:
            timed_out = len(uids) - n + 1
            print(f"time limit reached; {timed_out} studies left for fallback", flush=True)
            break
        states[item["state"]] += 1
        syntaxes.update(item["syntaxes"])
        errors.update(item["errors"])
        if item["state"] == "failed":
            print(f"study {item['i']} FAILED: {item['errors']} (selected series {item['n_selected_series']})", flush=True)
            continue
        if item["state"] == "degraded":
            print(f"study {item['i']} degraded: {item['errors']}", flush=True)
        windows.append(int(item["mask"][VIEWS[0]].sum()))
        for k, (spec, model) in enumerate(models):
            try:
                view = (spec["mirror"], spec["windows"], spec.get("slots", 3))
                x, mask = item["x"][view][None].to(device), item["mask"][view][None].to(device)
                with torch.inference_mode(), torch.autocast(device.type, dtype=torch.float16, enabled=device.type == "cuda"):
                    logits = model(prep(x, spec["res"]), mask).float()
                p = torch.sigmoid(logits)[0].cpu().numpy()
                if p.shape != (len(TARGETS),) or not np.isfinite(p).all():
                    raise FloatingPointError("nonfinite or misshaped probabilities")
                probs[k, item["i"]] = p
            except Exception as exc:
                model_failures[f"{spec['name']}:{type(exc).__name__}"] += 1
                print(f"study {item['i']} model {spec['name']} FAILED: {exc!r}", flush=True)
        if n % 100 == 0:
            print(f"processed {n}/{len(uids)} in {time.monotonic() - T0:.0f}s", flush=True)

    ok = np.isfinite(probs).all(2)  # (model, study)
    if not ok.any():
        raise RuntimeError("no study could be predicted")
    for k, (spec, _) in enumerate(models):
        write_csv(OUT / f"probs_{spec['name']}.csv", columns, uids, probs[k])
    if len(models) == 1:
        score = probs[0].copy()
    else:  # per-model, per-finding rank percentile over the studies that model predicted
        ranks = np.full(probs.shape, np.nan)
        for k in range(len(models)):
            if ok[k].any():
                ranks[k, ok[k]] = rankdata(probs[k, ok[k]], axis=0) / ok[k].sum()
        with np.errstate(invalid="ignore"):
            score = np.nanmean(ranks, axis=0)
    good = np.isfinite(score).all(1)
    fallback = score[good].mean(0)
    n_fallback = int((~good).sum())
    name = "probs_" + CONFIG["models"][0]["name"] + ".csv"
    if PARITY_UIDS is None:
        score[~good] = fallback
        name = "submission.csv"
        write_csv(OUT / name, columns, uids, score)
    summary = {"status": "complete", "mode": "parity" if PARITY_UIDS is not None else "submission",
               "device": str(device), "studies": len(uids),
               "studies_ok": states["ok"], "studies_degraded": states["degraded"],
               "studies_failed": states["failed"], "studies_timed_out": timed_out,
               "studies_mean_fallback": n_fallback, "model_failures": dict(model_failures),
               "studies_per_model": {s["name"]: int(ok[k].sum()) for k, (s, _) in enumerate(models)},
               "studies_with_all_models": int(ok.all(0).sum()), "fallback_vector": fallback.round(6).tolist(),
               "errors": dict(errors), "transfer_syntaxes": dict(syntaxes),
               "valid_windows_min_median_max": [min(windows), float(np.median(windows)), max(windows)] if windows else None,
               "config": CONFIG["run"],
               "output_sha256": sha256(OUT / name), "elapsed_s": round(time.monotonic() - T0, 1),
               "gpu_peak_reserved_bytes": torch.cuda.max_memory_reserved() if device.type == "cuda" else 0}
    (OUT / "v3_inference_summary.json").write_text(json.dumps(summary, indent=2) + "\n")
    print(json.dumps(summary), flush=True)


if __name__ == "__main__":
    main()
